#ifndef ASCON_PB_A
#define ASCON_PB_A 12        // rounds of p^a (initialisation / finalisation, hashing)
#endif
#define ROR64(x, n) (((x) >> (n)) | ((x) << (64 - (n))))

typedef struct { u64 x[5]; } AState;

static u64 be64(const u8 *p) { u64 r = 0; for (int i = 0; i < 8; i++) r = r << 8 | p[i]; return r; }
static void put64(u8 *p, u64 v) { for (int i = 7; i >= 0; i--) { p[i] = (u8)v; v >>= 8; } }
// load n (<= 8) bytes into the most significant end of a word, zero-padded
static u64 load_part(const u8 *p, int n) { u64 r = 0; for (int i = 0; i < 8; i++) r = r << 8 | (i < n ? p[i] : 0); return r; }

// p^rounds: the last `rounds` of the 12 constants
static void permute(AState *s, int rounds) {
    u64 x0 = s->x[0], x1 = s->x[1], x2 = s->x[2], x3 = s->x[3], x4 = s->x[4];
    for (int i = 12 - rounds; i < 12; i++) {
        x2 ^= (u64)(((15 - i) << 4) | i);
        x0 ^= x4; x4 ^= x3; x2 ^= x1;                                   // substitution layer
        u64 t0 = ~x0 & x1, t1 = ~x1 & x2, t2 = ~x2 & x3, t3 = ~x3 & x4, t4 = ~x4 & x0;
        x0 ^= t1; x1 ^= t2; x2 ^= t3; x3 ^= t4; x4 ^= t0;
        x1 ^= x0; x0 ^= x4; x3 ^= x2; x2 = ~x2;
        x0 ^= ROR64(x0, 19) ^ ROR64(x0, 28);                            // linear layer
        x1 ^= ROR64(x1, 61) ^ ROR64(x1, 39);
        x2 ^= ROR64(x2, 1)  ^ ROR64(x2, 6);
        x3 ^= ROR64(x3, 10) ^ ROR64(x3, 17);
        x4 ^= ROR64(x4, 7)  ^ ROR64(x4, 41);
    }
    s->x[0] = x0; s->x[1] = x1; s->x[2] = x2; s->x[3] = x3; s->x[4] = x4;
}

// ---- AEAD (variants: 0 = Ascon-128, 1 = Ascon-128a, 2 = Ascon-80pq) ---------------------------------------------------
static int rate_of(int v) { return v == 1 ? 16 : 8; }
static int pb_of(int v) { return v == 1 ? 8 : 6; }
static int klen_of(int v) { return v == 2 ? 20 : 16; }

// absorb/xor a block of `n` (<= rate) message bytes into the rate part of the state (bytes 0..rate-1 of x0 [|| x1])
static void xor_rate(AState *s, int rate, const u8 *blk, int n, int pad) {
    u8 b[16]; for (int i = 0; i < 16; i++) b[i] = 0;
    for (int i = 0; i < n; i++) b[i] = blk[i];
    if (pad) b[n] = 0x80;
    s->x[0] ^= be64(b); if (rate == 16) s->x[1] ^= be64(b + 8);
}
static void get_rate(const AState *s, int rate, u8 b[16]) { put64(b, s->x[0]); if (rate == 16) put64(b + 8, s->x[1]); }

static void aead_init(AState *s, int v, const u8 *k, const u8 *n) {
    if (v == 2) {
        s->x[0] = (0xa0400c06ULL << 32) | (be64(k) >> 32);
        s->x[1] = (be64(k) << 32) | (be64(k + 8) >> 32);
        s->x[2] = (be64(k + 8) << 32) | (be64(k + 16) >> 32);
    } else {
        s->x[0] = v == 1 ? 0x80800c0800000000ULL : 0x80400c0600000000ULL;
        s->x[1] = be64(k); s->x[2] = be64(k + 8);
    }
    s->x[3] = be64(n); s->x[4] = be64(n + 8);
    permute(s, ASCON_PB_A);
    if (v == 2) { s->x[2] ^= be64(k) >> 32; s->x[3] ^= (be64(k) << 32) | (be64(k + 8) >> 32); s->x[4] ^= (be64(k + 8) << 32) | (be64(k + 16) >> 32); }
    else { s->x[3] ^= be64(k); s->x[4] ^= be64(k + 8); }
}
static void aead_absorb_ad(AState *s, int v, const u8 *ad, int adlen) {
    int r = rate_of(v);
    if (adlen > 0) {
        int off = 0;
        while (adlen - off >= r) { xor_rate(s, r, ad + off, r, 0); permute(s, pb_of(v)); off += r; }
        xor_rate(s, r, ad + off, adlen - off, 1); permute(s, pb_of(v));
    }
    s->x[4] ^= 1;
}
static void aead_final(AState *s, int v, const u8 *k, u8 tag[16]) {
    if (v == 1) { s->x[2] ^= be64(k); s->x[3] ^= be64(k + 8); }
    else if (v == 0) { s->x[1] ^= be64(k); s->x[2] ^= be64(k + 8); }
    else { s->x[1] ^= be64(k); s->x[2] ^= be64(k + 8); s->x[3] ^= be64(k + 16) & 0xffffffff00000000ULL; }
    permute(s, ASCON_PB_A);
    const u8 *kt = v == 2 ? k + 4 : k;                 // the last 128 bits of the key
    put64(tag, s->x[3] ^ be64(kt)); put64(tag + 8, s->x[4] ^ be64(kt + 8));
}
static void aead_encrypt(int v, const u8 *k, const u8 *n, const u8 *ad, int adlen, const u8 *m, int mlen, u8 *c /* mlen + 16 */) {
    AState s; int r = rate_of(v);
    aead_init(&s, v, k, n); aead_absorb_ad(&s, v, ad, adlen);
    int off = 0; u8 b[16];
    while (mlen - off >= r) {
        xor_rate(&s, r, m + off, r, 0); get_rate(&s, r, b);
        for (int i = 0; i < r; i++) c[off + i] = b[i];
        permute(&s, pb_of(v)); off += r;
    }
    xor_rate(&s, r, m + off, mlen - off, 1); get_rate(&s, r, b);
    for (int i = 0; i < mlen - off; i++) c[off + i] = b[i];
    aead_final(&s, v, k, c + mlen);
}
// returns 1 if the tag verifies (then m holds the plaintext)
static int aead_decrypt(int v, const u8 *k, const u8 *n, const u8 *ad, int adlen, const u8 *c, int clen, u8 *m) {
    AState s; int r = rate_of(v), mlen = clen - 16;
    aead_init(&s, v, k, n); aead_absorb_ad(&s, v, ad, adlen);
    int off = 0; u8 b[16];
    while (mlen - off >= r) {
        get_rate(&s, r, b);
        for (int i = 0; i < r; i++) m[off + i] = b[i] ^ c[off + i];
        for (int i = 0; i < r; i++) b[i] = c[off + i];
        s.x[0] = be64(b); if (r == 16) s.x[1] = be64(b + 8);
        permute(&s, pb_of(v)); off += r;
    }
    int rem = mlen - off;
    get_rate(&s, r, b);
    for (int i = 0; i < rem; i++) { m[off + i] = b[i] ^ c[off + i]; b[i] = c[off + i]; }
    b[rem] ^= 0x80;                      // state bytes beyond the ciphertext keep their value; padding bit is xored in
    s.x[0] = be64(b); if (r == 16) s.x[1] = be64(b + 8);
    u8 tag[16]; aead_final(&s, v, k, tag);
    int diff = 0; for (int i = 0; i < 16; i++) diff |= tag[i] ^ c[mlen + i];
    return diff == 0;
}

// ---- hashing (variants: 0 = Hash, 1 = Hasha, 2 = Xof, 3 = Xofa) ---------------------------------------------------------
static void hash_run(int v, const u8 *m, int mlen, u8 out[32]) {
    static const u64 IV[4] = {0x00400c0000000100ULL, 0x00400c0400000100ULL, 0x00400c0000000000ULL, 0x00400c0400000000ULL};
    int pb = (v & 1) ? 8 : 12;
    AState s; s.x[0] = IV[v]; s.x[1] = s.x[2] = s.x[3] = s.x[4] = 0;
    permute(&s, ASCON_PB_A);
    int off = 0;
    while (mlen - off >= 8) { s.x[0] ^= be64(m + off); permute(&s, pb); off += 8; }
    s.x[0] ^= load_part(m + off, mlen - off) | (0x80ULL << (56 - 8 * (mlen - off)));
    permute(&s, ASCON_PB_A);
    for (int i = 0; i < 4; i++) { put64(out + 8 * i, s.x[0]); if (i < 3) permute(&s, pb); }
}

static int hexval(char c) { return c <= '9' ? c - '0' : c - 'a' + 10; }
static u8 hexbyte(const char *p) { return (u8)(hexval(p[0]) * 16 + hexval(p[1])); }

static u8 SEQ[1100];

static int run_aead(const char *name, int v, const char *cts) {
    u8 key[24], nonce[16], c[64], m2[64];
    for (int i = 0; i < 24; i++) key[i] = (u8)i;   // 80pq uses 20 bytes; the buffer is 24 so 64-bit loads stay in bounds
    for (int i = 0; i < 16; i++) nonce[i] = (u8)i;
    int enc_ok = 0, dec_ok = 0, rej_ok = 0, pos = 0;
    for (int idx = 0; idx < 1089; idx++) {
        int pl = idx / 33, al = idx % 33, cl = pl + 16;
        u8 want[48]; for (int i = 0; i < cl; i++) want[i] = hexbyte(cts + 2 * (pos + i));
        pos += cl;
        aead_encrypt(v, key, nonce, SEQ, al, SEQ, pl, c);
        int e = 1; for (int i = 0; i < cl; i++) if (c[i] != want[i]) e = 0;
        enc_ok += e;
        int d = aead_decrypt(v, key, nonce, SEQ, al, want, cl, m2);
        for (int i = 0; i < pl; i++) if (m2[i] != SEQ[i]) d = 0;
        dec_ok += d;
        want[cl - 1] ^= 1;                                   // sanity (not a published value): a modified tag must be rejected
        rej_ok += !aead_decrypt(v, key, nonce, SEQ, al, want, cl, m2);
    }
    pstr(name); pstr(": encryption "); pdec(enc_ok); pstr(" of 1089, decryption "); pdec(dec_ok); pstr(" of 1089, modified tag rejected (program sanity check) "); pdec(rej_ok); pstr(" of 1089\n");
    return enc_ok == 1089 && dec_ok == 1089 && rej_ok == 1089;
}
static int run_hash(const char *name, int v, const char *mds) {
    int good = 0;
    for (int len = 0; len <= 1024; len++) {
        u8 o[32]; hash_run(v, SEQ, len, o);
        int m = 1; for (int i = 0; i < 32; i++) if (o[i] != hexbyte(mds + 64 * len + 2 * i)) m = 0;
        good += m;
    }
    pstr(name); pstr(": "); pdec(good); pstr(" of 1025 digests match\n");
    return good == 1025;
}

int paper_main(void) {
    for (int i = 0; i < 1100; i++) SEQ[i] = (u8)i;
    int ok = 1;
    ok &= run_aead("Ascon-128", 0, A128_CT);
    ok &= run_aead("Ascon-128a", 1, A128A_CT);
    ok &= run_aead("Ascon-80pq", 2, A80PQ_CT);
    ok &= run_hash("Ascon-Hash", 0, HASH_MD);
    ok &= run_hash("Ascon-Hasha", 1, HASHA_MD);
    ok &= run_hash("Ascon-Xof (32 bytes)", 2, XOF_MD);
    ok &= run_hash("Ascon-Xofa (32 bytes)", 3, XOFA_MD);
    pstr(ok ? "PASS\n" : "FAIL\n");
    return ok ? 0 : 1;
}
